// 📊 【管理後台與戰情室專用 API】
// ----------------------------------------------------------------------------

function API_VerifyAdmin(pwd) {
  const realPwd = TOOLBOX_GetConfig("後台登入密碼");
  return pwd === realPwd || (realPwd === "" && pwd === "admin123");
}

function API_GetDashboardData(pwd) {
  if (!API_VerifyAdmin(pwd)) throw new Error("無效的密碼或登入已過期");

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const reqSheet = ss.getSheetByName(CONFIG.SHEET_REQUESTS);
  const reqData = reqSheet.getDataRange().getValues();
  const now = new Date().getTime();
  const oneDayMs = 24 * 60 * 60 * 1000;

  let validRequests = [];

  for (let i = reqData.length - 1; i > 0; i--) {
    const row = reqData[i];
    let slots = [];
    try { slots = JSON.parse(row[10] || "[]"); } catch(e) {}

    let maxEndTimeMs = 0;
    let minStartTimeMs = Infinity;
    let firstSlotStr = ""; 
    let totalSlotCount = 0; 

    slots.forEach(slot => {
      slot.dates.split(', ').forEach(d => {
        const pureDate = d.substring(0, 10);
        const endMs = new Date(`${pureDate}T${slot.endTime}:00`).getTime();
        if (endMs > maxEndTimeMs) maxEndTimeMs = endMs;
        const startMs = new Date(`${pureDate}T${slot.startTime}:00`).getTime();
        if (startMs < minStartTimeMs) minStartTimeMs = startMs;
        if (totalSlotCount === 0) firstSlotStr = `${pureDate} | ${slot.startTime} ~ ${slot.endTime}`;
        totalSlotCount++;
      });
    });

    if (maxEndTimeMs > 0 && (maxEndTimeMs + oneDayMs) < now) {
      reqSheet.deleteRow(i + 1); 
    } else {
      const currentStatus = String(row[2] || "").trim();
      const remarksStr = String(row[9] || "");
      
      // 🛡️ 新增：解析是否有衝突標記，並派發給前端
      const hasConflict = remarksStr.includes("[已發送衝突警告]");

      if (currentStatus === "待審核" || currentStatus === "已同意") {
        let submitTimeStr = row[1] instanceof Date ? Utilities.formatDate(row[1], "Asia/Taipei", "yyyy/MM/dd HH:mm:ss") : String(row[1] || "");
        let summary = firstSlotStr;
        if (totalSlotCount > 1) summary += " <span class='text-xs font-bold bg-white bg-opacity-70 px-2 py-0.5 rounded-full ml-1'>(多時段)</span>";
        else if (totalSlotCount === 0) summary = "無有效時段";

        validRequests.push({
          id: String(row[0] || ""),
          submitTime: submitTimeStr,
          status: currentStatus,
          name: String(row[3] || ""),
          email: String(row[4] || ""),
          unit: String(row[5] || ""),
          phone: String(row[6] || ""),
          location: String(row[7] || ""),
          reason: String(row[8] || ""),
          remarks: remarksStr,
          slotsHtml: TOOLBOX_GenerateSlotsHtml(slots),
          timeSummary: summary, 
          sortTime: minStartTimeMs === Infinity ? 0 : minStartTimeMs,
          hasConflict: hasConflict // 傳遞給前端作為變色判斷依據
        });
      }
    }
  }

  validRequests.sort((a, b) => a.sortTime - b.sortTime);

  const setSheet = ss.getSheetByName(CONFIG.SHEET_SETTINGS);
  const setValues = setSheet.getDataRange().getValues();
  const settings = [];
  
  for (let i = 0; i < setValues.length; i++) {
    const key = String(setValues[i][0] || "").trim();
    if (key === "" || key.includes("⚠️") || key === "設定項目") continue;
    settings.push({ key: key, value: String(setValues[i][1] || ""), desc: String(setValues[i][2] || "") });
  }

  return { requests: validRequests, settings: settings };
}

function TOOLBOX_GenerateSlotsHtml(slots) {
  if (!slots || slots.length === 0) return "<span class='text-slate-400'>無時段資料</span>";
  let html = '<ul class="list-disc pl-5 space-y-1 text-sm">';
  slots.forEach(s => { html += `<li>${s.dates} | ${s.startTime} ~ ${s.endTime}</li>`; });
  html += '</ul>';
  return html;
}

function API_SaveSettings(pwd, newSettings) {
  if (!API_VerifyAdmin(pwd)) throw new Error("無效的密碼或登入已過期");
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(CONFIG.SHEET_SETTINGS);
  const props = PropertiesService.getScriptProperties();
  const data = sheet.getDataRange().getValues();

  newSettings.forEach(newSet => {
    const key = newSet.key.trim();
    let val = newSet.value.trim();
    let rowIndex = -1;
    for (let i = 1; i < data.length; i++) {
      if (String(data[i][0]).trim() === key) { rowIndex = i + 1; break; }
    }
    if (rowIndex !== -1) {
      if ((key.includes("SECRET") || key.includes("KEY") || key.includes("密碼")) && val) {
        if (!val.includes("***")) {
          props.setProperty(CONFIG.KEY_PREFIX + key, val);
          const masked = val.length > 8 ? val.substring(0, 4) + "***" + val.substring(val.length - 4) : "***(已安全儲存)";
          sheet.getRange(rowIndex, 2).setValue(masked).setFontColor("#059669").setFontWeight("bold");
        }
      } else {
        sheet.getRange(rowIndex, 2).setValue(val).setFontColor("#000000").setFontWeight("normal");
      }
    }
  });
  return "✅ 設定儲存成功！系統已更新。";
}

// 💥 新增：戰情室專屬的「一鍵撤銷與刪除行事曆」API
function API_CancelRequest(pwd, id) {
  if (!API_VerifyAdmin(pwd)) throw new Error("無效的密碼或登入已過期");
  
  const lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const sheet = ss.getSheetByName(CONFIG.SHEET_REQUESTS);
    const data = sheet.getDataRange().getValues();
    
    let rowIndex = -1;
    let currentStatus = "";
    for (let i = 1; i < data.length; i++) {
      if (data[i][0] === id) { 
        rowIndex = i + 1; 
        currentStatus = data[i][2]; 
        break; 
      }
    }

    if (rowIndex === -1) throw new Error("找不到該單號");
    if (currentStatus === "已退回" || currentStatus === "已取消") throw new Error("該單據已處於失效狀態，無法再次撤銷");

    // 更新狀態
    sheet.getRange(rowIndex, 3).setValue("已取消");

    // 若原狀態為已同意，啟動行事曆淨化引擎
    let msg = "✅ 撤單成功！單據狀態已更新為「已取消」。";
    if (currentStatus === "已同意") {
      TOOLBOX_DeleteCalendarEvents(id);
      msg = "✅ 撤單成功！單據已取消，並已自動淨化行事曆上相關的幽靈事件。";
    }

    return msg;
  } finally {
    lock.releaseLock();
  }
}